struct Item { int id; };

// Vector of unique ownership (std::unique_ptr)
std::vector<std::unique_ptr<Item>> unique_items;

// Insertion requires move semantics
unique_items.push_back(std::make_unique<Item>(1));
unique_items.emplace_back(new Item{2});

// Iteration and access
for (const auto& ptr : unique_items) {
    if (ptr) {
        ptr->id = 100; // Accessing the managed object
    }
}

// List of shared ownership (std::shared_ptr)
std::list<std::shared_ptr<Item>> shared_items;

auto item_ref = std::make_shared<Item>(3);

// Insertion copies the pointer, increments ref count
shared_items.push_back(item_ref);
shared_items.push_back(item_ref);
